export default function google() {
    let sessionToken = null;

    return {
        attribution,

        async suggest(query, { key }) {
            sessionToken ??= uuid();

            const response = await fetch('https://places.googleapis.com/v1/places:autocomplete', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Goog-Api-Key': key,
                },
                body: JSON.stringify({ input: query, sessionToken }),
            });

            if (!response.ok) return [];

            const { suggestions } = await response.json();

            return (suggestions ?? [])
                .filter((suggestion) => suggestion.placePrediction)
                .map(({ placePrediction }) => ({
                    id: placePrediction.placeId,
                    label: placePrediction.text?.text,
                }));
        },

        async retrieve({ id }, { key }) {
            const response = await fetch(`https://places.googleapis.com/v1/places/${id}?sessionToken=${sessionToken}`, {
                headers: {
                    'X-Goog-Api-Key': key,
                    'X-Goog-FieldMask': 'addressComponents',
                },
            });

            sessionToken = null;

            if (!response.ok) return null;

            const { addressComponents } = await response.json();

            const component = (type, name = 'longText') => {
                return addressComponents?.find((component) => component.types.includes(type))?.[name] ?? '';
            };

            const country = component('country', 'shortText');

            return {
                line_1: [component('street_number'), component('route')].filter(Boolean).join(' '),
                line_2: component('subpremise'),
                city: component('postal_town') || component('locality') || component('sublocality_level_1'),
                region: country === 'GB' ? component('administrative_area_level_2') : component('administrative_area_level_1'),
                postcode: component('postal_code'),
                country,
            };
        },
    };
}

function uuid() {
    return crypto.randomUUID
        ? crypto.randomUUID()
        : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
            const r = (Math.random() * 16) | 0;
            return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
        });
}
